-- Açıklama   : Paket, kısmi sevk, karantinalı iade ve sağlayıcı para iadesi kayıtları.
CREATE TABLE shipments(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,fulfillment_group_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,carrier VARCHAR(100) NOT NULL,tracking_number VARCHAR(200) COLLATE utf8mb4_0900_bin NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'shipped',cost_minor BIGINT,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(carrier,tracking_number),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(fulfillment_group_id,order_id) REFERENCES order_fulfillment_groups(id,order_id),CHECK(status IN('shipped','delivered','exception')),CHECK(cost_minor IS NULL OR cost_minor>=0)) ENGINE=InnoDB;
CREATE TABLE shipment_items(shipment_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,PRIMARY KEY(shipment_id,variant_id),FOREIGN KEY(shipment_id) REFERENCES shipments(id),FOREIGN KEY(variant_id) REFERENCES variants(id),CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE fulfillment_tasks(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'picking',shipment_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(shipment_id) REFERENCES shipments(id),CHECK(status IN('picking','packing','packed','shipped','cancelled'))) ENGINE=InnoDB;
CREATE TABLE fulfillment_task_items(task_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,picked_quantity INT NOT NULL DEFAULT 0,packed_quantity INT NOT NULL DEFAULT 0,PRIMARY KEY(task_id,variant_id),FOREIGN KEY(task_id) REFERENCES fulfillment_tasks(id),FOREIGN KEY(variant_id) REFERENCES variants(id),CHECK(quantity>0 AND picked_quantity BETWEEN 0 AND quantity AND packed_quantity BETWEEN 0 AND picked_quantity)) ENGINE=InnoDB;
CREATE TABLE returns(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,reason TEXT NOT NULL,seal_status VARCHAR(16) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'requested',decision_reason TEXT,receipt_reference TEXT,disposition VARCHAR(20),quality_notes TEXT,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id,variant_id) REFERENCES order_items(order_id,variant_id),CHECK(quantity>0),CHECK(seal_status IN('unopened','opened','unknown')),CHECK(status IN('requested','approved','rejected','received','inspected','refund_pending','refund_failed','refunded')),CHECK(disposition IS NULL OR disposition IN('restock','dispose','quarantine'))) ENGINE=InnoDB;
CREATE TABLE return_stock_lines(return_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,warehouse_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,PRIMARY KEY(return_id,variant_id,warehouse_id),FOREIGN KEY(return_id) REFERENCES returns(id),FOREIGN KEY(variant_id,warehouse_id) REFERENCES inventory_balance(variant_id,warehouse_id),CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE refunds(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,return_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,payment_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,amount_minor BIGINT NOT NULL,tax_minor BIGINT NOT NULL,discount_minor BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',provider_reference VARCHAR(255) COLLATE utf8mb4_0900_bin UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(return_id) REFERENCES returns(id),FOREIGN KEY(payment_id) REFERENCES payments(id),CHECK(amount_minor>0 AND tax_minor>=0 AND discount_minor>=0),CHECK(status IN('pending','succeeded','failed'))) ENGINE=InnoDB;
CREATE TABLE invoice_references(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,provider VARCHAR(100) NOT NULL,external_reference VARCHAR(200) NOT NULL,document_kind VARCHAR(30) NOT NULL,note TEXT NOT NULL,actor_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(provider,external_reference),FOREIGN KEY(order_id) REFERENCES orders(id),CHECK(document_kind IN('e-invoice','e-archive','external-invoice'))) ENGINE=InnoDB;
